BEGIN;
-- Product-authorised occupation guidance. This never changes employer job fields.
-- Existing taxonomy nodes/relationships remain authoritative; no parallel tables.
DO $blueprints$
DECLARE role_data jsonb; field_name text; term jsonb; occupation uuid; target uuid; kind text; band text;
BEGIN
 FOR role_data IN SELECT * FROM jsonb_array_elements($catalog$[{"title":"Java Backend Developer","job_family":"Software Development","functional_area":"Engineering","industry_context":"Technology","about_role":"Develop and maintain Java backend services, data access and APIs with attention to reliability and maintainable code.","core_responsibilities":["Design and implement Java backend services around clear business and data requirements.","Build and document REST API endpoints with input validation and controlled failure responses.","Work with relational data models and SQL queries to support service operations.","Write automated tests and review code changes to keep backend services maintainable.","Investigate service defects using logs, reproduce issues and implement verified fixes.","Coordinate API and data changes with engineering colleagues and document technical decisions."],"core_skills":["Java","REST APIs","SQL","Git","Automated Testing"],"optional_skills":["Spring Boot","Container Fundamentals"],"common_tools":["Git"],"common_competencies":["Debugging","Code Review"],"typical_qualifications":[],"review_notes":["Confirm which optional frameworks and tools are relevant to this employer; no company stack is assumed."]},{"title":"Registered Nurse","job_family":"Nursing","functional_area":"Clinical Care","industry_context":"Healthcare","about_role":"Support patient assessment, nursing care and clear clinical handovers within the agreed clinical scope.","core_responsibilities":["Assess assigned patients and record observations so changes in care needs are visible.","Carry out agreed nursing care activities within the role's clinical scope and patient care plan.","Support prescribed medication administration using verified clinical procedures and accurate records.","Maintain clear clinical documentation and communicate relevant changes to the care team.","Apply infection prevention practices when preparing equipment and supporting patient care.","Prepare structured patient handovers and explain care information respectfully to patients and carers."],"core_skills":["Patient Assessment","Clinical Documentation","Medication Administration","Infection Prevention","Patient Handover"],"optional_skills":["Emergency Response","Wound Care"],"common_tools":[],"common_competencies":["Patient Communication"],"typical_qualifications":[],"review_notes":["Confirm nursing registration, clinical scope and jurisdiction with the hiring team; no specific licence is asserted."]},{"title":"Relationship Manager","job_family":"Client Relationship Management","functional_area":"Sales and Service","industry_context":"Banking and Financial Services","about_role":"Develop client relationships, understand service needs and coordinate timely follow-up with relevant teams.","core_responsibilities":["Build and maintain client relationships through clear communication and planned follow-up.","Understand client needs and document relevant information before discussing suitable service options.","Coordinate responses to client queries with service and operational colleagues.","Maintain accurate relationship records and track agreed client actions to completion.","Review account activity to identify service gaps and prepare practical account plans.","Prepare relationship updates and communicate client feedback to the appropriate teams."],"core_skills":["Relationship Management","Client Communication","Account Planning","Needs Assessment","Record Keeping"],"optional_skills":["CRM Systems","Negotiation"],"common_tools":["CRM Systems"],"common_competencies":["Service Coordination"],"typical_qualifications":[],"review_notes":["Confirm the industry and service scope; no financial product, sales quota or regulatory credential is assumed."]},{"title":"CNC Machine Operator","job_family":"Manufacturing Operations","functional_area":"Production","industry_context":"Manufacturing","about_role":"Prepare and operate CNC equipment, interpret production drawings and check finished work against specifications.","core_responsibilities":["Read production drawings and identify dimensions, tolerances and machining instructions.","Prepare machine setups, tooling and workholding arrangements for the assigned production work.","Operate CNC equipment and monitor the machining process for changes or visible defects.","Measure finished components and record inspection results against the supplied specifications.","Report machine faults and coordinate corrective action before affected work continues.","Maintain orderly work areas and record production progress, tool changes and handover information."],"core_skills":["CNC Operation","Blueprint Interpretation","Machine Setup","Dimensional Measurement","Quality Inspection"],"optional_skills":["CNC Programming Fundamentals","Tool Maintenance"],"common_tools":["Precision Measuring Tools"],"common_competencies":["Production Record Keeping"],"typical_qualifications":[],"review_notes":["Confirm machine type and control system; no brand, shift pattern or certification is assumed."]},{"title":"Warehouse Supervisor","job_family":"Warehouse Operations","functional_area":"Supply Chain","industry_context":"Logistics","about_role":"Coordinate receiving, storage, inventory and dispatch work while supporting accurate warehouse records and team handovers.","core_responsibilities":["Coordinate incoming goods checks and record discrepancies for receiving follow-up.","Organise storage and replenishment work so goods remain identifiable and accessible.","Plan picking, packing and dispatch priorities with the warehouse team.","Review stock counts and investigate inventory differences using warehouse records.","Brief colleagues on assigned warehouse work and monitor progress against agreed priorities.","Maintain clear handovers and report damaged goods, equipment issues and workflow delays."],"core_skills":["Warehouse Operations","Inventory Control","Dispatch Coordination","Team Coordination","Stock Reconciliation"],"optional_skills":["Warehouse Management Systems","Material Handling Awareness"],"common_tools":["Warehouse Management Systems"],"common_competencies":["Operational Handover"],"typical_qualifications":[],"review_notes":["Confirm equipment and warehouse scope; no forklift licence, hours or shift schedule is assumed."]},{"title":"Primary School Teacher","job_family":"Primary Education","functional_area":"Teaching","industry_context":"Education","about_role":"Plan age-appropriate lessons, support pupils' learning and use classroom assessment to guide teaching.","core_responsibilities":["Plan primary-school lessons around the agreed curriculum and pupils' learning needs.","Prepare learning activities and resources that make lesson objectives understandable.","Teach and adapt classroom activities to support pupils with different learning needs.","Assess pupil work and use observations to plan the next learning steps.","Maintain a supportive classroom environment and communicate expectations clearly.","Record pupil progress and share relevant learning updates with colleagues and carers."],"core_skills":["Lesson Planning","Classroom Management","Pupil Assessment","Inclusive Teaching","Learning Communication"],"optional_skills":["Digital Learning Tools","Curriculum Adaptation"],"common_tools":["Digital Learning Tools"],"common_competencies":["Learning Resource Preparation"],"typical_qualifications":[],"review_notes":["Confirm curriculum, year group and any jurisdiction-specific teaching requirements; no degree or teaching certificate is assumed."]},{"title":"Hotel Operations Manager","job_family":"Hospitality Operations","functional_area":"Hotel Management","industry_context":"Hospitality","about_role":"Coordinate hotel operating departments, resolve guest-service issues and support consistent operational handovers.","core_responsibilities":["Coordinate daily hotel operating priorities with the relevant department leads.","Review guest feedback and organise follow-up on service issues and unresolved requests.","Support coordination between front office, housekeeping and maintenance activities.","Review operational records to identify service delays and practical improvements.","Brief department colleagues on agreed actions and track progress through clear handovers.","Maintain operational reports and communicate resource or maintenance concerns to the appropriate teams."],"core_skills":["Hotel Operations","Guest Services","Department Coordination","Service Recovery","Operational Reporting"],"optional_skills":["Property Management Systems","Service Quality Review"],"common_tools":["Property Management Systems"],"common_competencies":["Operational Handover"],"typical_qualifications":[],"review_notes":["Confirm the property's operating scope; no hotel brand, star rating, working hours or benefit is assumed."]},{"title":"Industrial Electrician","job_family":"Electrical Maintenance","functional_area":"Technical Operations","industry_context":"Industrial Services","about_role":"Inspect, install and maintain industrial electrical equipment using systematic fault diagnosis and clear maintenance records.","core_responsibilities":["Read electrical drawings to understand equipment connections and the planned work scope.","Inspect electrical equipment and record visible defects or abnormal operating conditions.","Coordinate safe isolation with authorised colleagues before inspecting or working on circuits.","Use suitable electrical test methods to investigate faults and document findings.","Install or replace assigned electrical components and verify the completed work.","Maintain service records and communicate unresolved faults and maintenance needs at handover."],"core_skills":["Electrical Drawings","Electrical Testing","Fault Diagnosis","Electrical Maintenance","Isolation Awareness"],"optional_skills":["PLC Fundamentals","Industrial Automation Awareness"],"common_tools":["Electrical Test Instruments"],"common_competencies":["Maintenance Documentation"],"typical_qualifications":[],"review_notes":["Confirm permitted work scope and local authorisation requirements; no specific licence, voltage range or shift pattern is assumed."]}]$catalog$::jsonb) LOOP
  INSERT INTO workforce.taxonomy_entities(entity_type,canonical_name,normalized_name,metadata)
  VALUES('occupation',role_data->>'title',workforce.normalize_term(role_data->>'title'),'{}')
  ON CONFLICT(entity_type,normalized_name,country_scope,language_code) DO NOTHING;
  SELECT id INTO STRICT occupation FROM workforce.taxonomy_entities WHERE entity_type='occupation' AND normalized_name=workforce.normalize_term(role_data->>'title') AND country_scope='' AND language_code='en';
  UPDATE workforce.taxonomy_entities SET metadata=jsonb_set(metadata,'{jd_generation_blueprint_v1_1}',
    (role_data - ARRAY['title','core_skills','optional_skills','common_tools','common_competencies','job_family','functional_area','industry_context']) ||
    jsonb_build_object('version','rb-1.1','approval_status','approved','source','product_authorised_occupation_guidance','employer_policy',false)) WHERE id=occupation;
  FOREACH field_name IN ARRAY ARRAY['core_skills','optional_skills','common_tools','common_competencies','job_family','functional_area','industry_context'] LOOP
   kind:=CASE field_name WHEN 'job_family' THEN 'job_family' WHEN 'functional_area' THEN 'functional_area' WHEN 'industry_context' THEN 'industry' ELSE 'competency' END;
   band:=field_name;
   FOR term IN SELECT * FROM jsonb_array_elements(CASE WHEN jsonb_typeof(role_data->field_name)='array' THEN role_data->field_name ELSE jsonb_build_array(role_data->field_name) END) LOOP
    INSERT INTO workforce.taxonomy_entities(entity_type,canonical_name,normalized_name,metadata)
    VALUES(kind,term#>>'{}',workforce.normalize_term(term#>>'{}'),'{}')
    ON CONFLICT(entity_type,normalized_name,country_scope,language_code) DO NOTHING;
    SELECT id INTO STRICT target FROM workforce.taxonomy_entities WHERE entity_type=kind AND normalized_name=workforce.normalize_term(term#>>'{}') AND country_scope='' AND language_code='en';
    INSERT INTO workforce.taxonomy_relationships(source_entity_id,target_entity_id,relationship_type,source,metadata)
    VALUES(occupation,target,CASE WHEN kind='competency' THEN 'occupation_competency' ELSE 'occupation_'||kind END,'jd_blueprint_v1_1',jsonb_build_object('jd_generation_v1_1_'||band,true))
    ON CONFLICT(source_entity_id,target_entity_id,relationship_type) DO UPDATE SET metadata=workforce.taxonomy_relationships.metadata||EXCLUDED.metadata;
   END LOOP;
  END LOOP;
 END LOOP;
END $blueprints$;
COMMIT;
